#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, M;
    cin >> n >> M;

    vector<vector<int>> D(n + 1);
    for (int d = 2; d <= n; ++d) {
        for (int dst = 2 * d; dst <= n; dst += d) {
            D[dst].push_back(d);
        }
    }

    vector<long long> F(n + 1, 0);
    F[1] = 1;
    if (n >= 2) F[2] = 2;

    for (int x = 3; x <= n; ++x) {
        long long val = (2LL * F[x - 1]) % M;
        long long divisor_part = F[x / (x - 1)];
        val = (val + divisor_part) % M;

        long long total = 0;
        for (int divisor : D[x]) {
            if (divisor >= 2 && divisor <= x - 2) {
                total += F[x / divisor] - F[(x - 1) / divisor];
            }
        }
        F[x] = (val + total) % M;
    }

    cout << F[n] % M << "\n";

    return 0;
}
